// saveOS E2E & Integration Cleanup — AUTO mode focus, non-forensic
// Generated by vibeOS 2026-05-22.
//
// GOALS:
//   1. Cover every saveOS feature with a passing test — not exhaustive, but survivable.
//   2. Delete dead tests that never pass / never run / duplicate with no delta.
//   3. Merge overlapping coverage into fewer, faster, clearer files.
//   4. AUTO mode (meta-controller) is the primary test surface.
//   5. Every critical path at least touched once: auto mode, lock, blackbox enable/disable,
//      stress routing, enforcement, TDD skeleton, flow rules, reports, patterns, API fallback.
//   6. NOT forensic — no 10-assertion deep-dives on one function. Breadth + sanity.

import test from "node:test"
import assert from "node:assert/strict"
import {
  mkdtempSync, mkdirSync, writeFileSync, readFileSync, existsSync,
} from "node:fs"
import { join } from "node:path"
import { tmpdir } from "node:os"

const sandbox = mkdtempSync(join(tmpdir(), "saveos-e2e-"))
process.env.HOME = sandbox
mkdirSync(join(sandbox, ".config/opencode"), { recursive: true })
mkdirSync(join(sandbox, ".claude/reports"), { recursive: true })
mkdirSync(join(sandbox, ".claude/scratch"), { recursive: true })
mkdirSync(join(sandbox, ".local/share/opencode"), { recursive: true })

const projectDir = join(sandbox, "my-project")
mkdirSync(projectDir, { recursive: true })
writeFileSync(join(projectDir, "opencode.json"), JSON.stringify({
  model: "deepseek/deepseek-v4-pro",
  provider: { deepseek: { models: { "deepseek-v4-pro": {}, "deepseek-v4-flash": {}, "deepseek-chat": {}, "deepseek-reasoner": {} } } }
}) + "\n")

writeFileSync(join(sandbox, ".config/opencode/opencode.json"), JSON.stringify({
  model: "deepseek/deepseek-v4-flash",
  provider: {
    opencode: {},
    deepseek: {
      models: { "deepseek-v4-pro": {}, "deepseek-v4-flash": {}, "deepseek-chat": {}, "deepseek-reasoner": {} }
    }
  }
}, null, 2) + "\n")

function seedTiers(overrides = {}) {
  writeFileSync(join(sandbox, ".claude/model-tiers.json"), JSON.stringify({
    trinity: {
      brain: { oc: "deepseek/deepseek-v4-pro" },
      medium: { oc: "deepseek/deepseek-v4-flash" },
      cheap: { oc: "deepseek/deepseek-chat" },
    },
    tiers: {
      high: { regex: "v4.*pro|v4-pro|opus|r1|reasoner" },
      mid: { regex: "v4.*flash|sonnet|4o" },
      budget: { regex: ".*" },
    },
    selection: {
      enabled: true, active_slot: "medium", delegation_enforce: true,
      flow_enabled: true, tdd_enabled: true, thinking_level: "off",
    },
    pricing: { deepseek: { "deepseek-chat": 0, "deepseek-v4-flash": 0.000182, "deepseek-v4-pro": 0.00057 } },
    ...overrides,
  }, null, 2) + "\n")
}

function seedDelegationState(overrides = {}) {
  writeFileSync(join(sandbox, ".claude/delegation-state.json"), JSON.stringify({
    lifetime: { warn_count: 5, cache_savings_usd: 2.1, missed_context7_usd: 0.3, total_savings_usd: 3.0, last_updated: "2026-05-22T00:00:00Z" },
    sessions: {
      "saveos-session-1": {
        model: "deepseek/deepseek-v4-pro",
        warns: [{ tool: "edit", reason: "high-tier direct edit", est_savings_usd: 0.12 }],
        cache_savings_usd: 0.8, cost_usd: 0.5,
      },
    },
  }, null, 2) + "\n")
}

async function loadPlugin() {
  return import("../src/index.js?t=" + Date.now())
}

async function freshPlugin(dir = projectDir) {
  seedTiers()
  seedDelegationState()
  const mod = await loadPlugin()
  const hooks = await mod.DelegationEnforcer({ client: {}, directory: dir })
  return { mod, hooks }
}

