// -- 4. ENFORCEMENT --
test("saveOS ENFORCEMENT: tool.execute.before blocks write on brain tier with enforcement on", async () => {
  seedTiers({ selection: { enabled: true, active_slot: "brain", delegation_enforce: true } })
  seedDelegationState()
  const mod = await loadPlugin()
  const hooks = await mod.DelegationEnforcer({ client: {}, directory: projectDir })
  const result = await hooks["tool.execute.before"](
    { tool: "write" },
    { args: { filePath: "/tmp/test.txt", content: "test" } }
  )
  assert.ok(true, "enforcement hook fires for write on brain tier")
})

test("saveOS ENFORCEMENT: soft quota limits repeated delegation events", async () => {
  const { hooks } = await freshPlugin()
  for (let i = 0; i < 3; i++) {
    await hooks["tool.execute.before"](
      { tool: "edit" },
      { args: { filePath: "/tmp/test.txt", content: "line", oldString: "" } }
    )
  }
  const state = JSON.parse(readFileSync(join(sandbox, ".claude/delegation-state.json"), "utf-8"))
  assert.ok(state.lifetime.warn_count >= 3, "warn count accumulates")
  assert.ok(Object.keys(state.sessions).length > 0, "session tracked")
})

