// -- 13. JSONC PARSING --
test("saveOS JSONC: safeJsonParse handles trailing commas and comments", async () => {
  await freshPlugin()
  const stateMod = await import("../src/lib/state.js?t=" + Date.now())
  if (typeof stateMod.safeJsonParse === "function") {
    const result = stateMod.safeJsonParse('{ "key": "value", "trailing": 1, }')
    assert.deepEqual(result, { key: "value", trailing: 1 }, "trailing comma handled")
    const result2 = stateMod.safeJsonParse('{ "key": "value" /* comment */ }')
    assert.deepEqual(result2, { key: "value" }, "JS comment handled")
  }
})

